#include <stdlib.h>
typedef struct Node { int data; struct Node *next; } Node;
Node *insert(Node *head, int value, int allocation_success) {
    Node *p = allocation_success ? malloc(sizeof *p) : NULL;
    if (p == NULL) return head;
    p->data = value;
    p->next = head;
    return p;
}
int main(void) {
    Node i0;
    Node i1;
    Node i2;
    i0.data = 10;
    i0.next = &i1;
    i1.data = 20;
    i1.next = &i2;
    i2.data = 30;
    i2.next = NULL;
    Node *caller_head = &i0;
    caller_head = insert(caller_head, 1, 1);
    caller_head = insert(caller_head, 2, 1);
    caller_head = insert(caller_head, 3, 1);
    caller_head = insert(caller_head, 4, 1);
    (void)caller_head;
    return 0;
}

